import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getComment } from "../handlers/getComment";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostCommentEntityType } from "../types/SpacePostCommentEntityType";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";

type Data = Awaited<ReturnType<typeof getComment>>;

export function useGetComment(
  spaceId: SpacePartition,
  discussionSk: SpacePostEntityType,
  commentSk: SpacePostCommentEntityType,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getComment", spaceId, discussionSk, commentSk],
    queryFn: () => getComment(spaceId, discussionSk, commentSk),
    ...options,
  });
}
